mapper.select:
 WHERE t.user_id=#{userId}
AND t.template_id=#{templateId}
ORDER BY t.id DESC LIMIT #{limit}

mapper.update:
UPDATE generation_task SET status='SUCCEEDED',result_key=#{resultKey},finished_at=#{now},updated_at=#{now}
WHERE id=#{id} AND status='PROCESSING' AND stage='RESULT_ASSEMBLY'
  AND EXISTS (SELECT 1 FROM generation_task_step s WHERE s.task_id=#{id} AND s.stage='RESULT_ASSEMBLY' AND s.status='SUCCEEDED')

UPDATE generation_task SET status='FAILED',stage=#{stage},failed_stage=#{stage},error_code=#{code},error_message=#{message},
  finished_at=#{now},updated_at=#{now}
WHERE id=#{id} AND status IN ('PENDING','PROCESSING') AND ((stage IS NULL AND #{stage} IS NULL) OR stage=#{stage})
